-- 執行後唯讀驗證：預期 18 欄位、5 個 text[]、兩 indexes；ledger 需由官方流程驗證。
select column_name,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name='properties' and column_name in ('contract_signed_date','sale_motivation','sale_motivation_other','current_condition_type','current_condition_other','current_usage','current_usage_other','building_style','building_style_other','parking_type','parking_type_other','road_width','completion_date','has_addition','addition_description','elementary_school_district','junior_high_school_district','showing_meeting_location') order by ordinal_position;
select conname,pg_get_constraintdef(oid) definition from pg_constraint where conrelid='public.properties'::regclass and conname in ('properties_sale_motivation_check','properties_current_condition_type_check','properties_current_usage_check','properties_building_style_check','properties_parking_type_check');
select indexname,indexdef from pg_indexes where schemaname='public' and tablename='properties' and indexname in ('properties_contract_signed_date_idx','properties_completion_date_idx');
select version from supabase_migrations.schema_migrations where version in ('202607280101','202607280102') order by version;
select count(*) total_after,count(*) filter(where sale_motivation is null or cardinality(sale_motivation)=0) empty_sale,count(*) filter(where current_condition_type is null) null_condition,count(*) filter(where current_usage is null) null_usage,count(*) filter(where building_style is null) null_style,count(*) filter(where parking_type is null) null_parking from public.properties;
select id,sale_motivation,current_condition_type,current_usage,building_style,parking_type,completion_date,road_width from public.properties order by id limit 20;
